args.sql:
SELECT upkeeprobot, faultpredscore FROM maintenance_and_fault WHERE (upkeeprobot, upkeepduedays) IN (
    SELECT upkeeprobot, MIN(upkeepduedays) FROM maintenance_and_fault GROUP BY upkeeprobot
) LIMIT 5;

SELECT upkeeprobot, COUNT(*) as cnt FROM (
    SELECT upkeeprobot, upkeepduedays FROM maintenance_and_fault WHERE (upkeeprobot, upkeepduedays) IN (
        SELECT upkeeprobot, MIN(upkeepduedays) FROM maintenance_and_fault GROUP BY upkeeprobot
    )
) t GROUP BY upkeeprobot HAVING COUNT(*) > 1 LIMIT 5;

